// ===============================================
// JobSlice.js
// ===============================================
// This slice handles all job-related operations:
// ✔️ Fetch jobs
// ✔️ Add job (for companies)
// ✔️ Apply for job (students)
// ===============================================

import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";
import * as ENV from "../config";

// ----------------------------------------------------
// 1) FETCH ALL JOBS
// ----------------------------------------------------
export const fetchJobs = createAsyncThunk("jobs/fetchJobs", async () => {
  // Get all jobs from backend
  const res = await axios.get(`${ENV.SERVER_URL}/jobs`);
  return res.data; // returns array of jobs
});

// ----------------------------------------------------
// 2) ADD NEW JOB (Company)
// ----------------------------------------------------
export const addJob = createAsyncThunk(
  "jobs/addJob",
  async (jobData, thunkAPI) => {
    try {
      const res = await axios.post(`${ENV.SERVER_URL}/addJob`, jobData);
      return res.data.job || res.data; // return created job
    } catch (error) {
      return thunkAPI.rejectWithValue(error.response?.data || "Add job failed");
    }
  }
);

// ----------------------------------------------------
// 3) APPLY FOR A JOB (Student)
// ----------------------------------------------------
// Instead of axios inside component, it's better to keep logic in Slice
export const applyForJob = createAsyncThunk(
  "jobs/applyForJob",
  async (applicationData, thunkAPI) => {
    try {
      const res = await axios.post(`${ENV.SERVER_URL}/apply`, applicationData);
      return res.data; // success message from backend
    } catch (err) {
      return thunkAPI.rejectWithValue(err.response?.data || "Apply failed");
    }
  }
);

// ----------------------------------------------------
// INITIAL STATE
// ----------------------------------------------------
const jobSlice = createSlice({
  name: "jobs",
  initialState: {
    jobs: [], // all jobs
    isLoading: false,
    isError: false,
    isSuccess: false,
    message: "",
  },

  reducers: {},

  extraReducers: (builder) => {
    builder
      // -------------------------------
      // FETCH JOBS
      // -------------------------------
      .addCase(fetchJobs.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(fetchJobs.fulfilled, (state, action) => {
        state.isLoading = false;
        state.jobs = action.payload;
      })
      .addCase(fetchJobs.rejected, (state) => {
        state.isLoading = false;
        state.isError = true;
      })

      // -------------------------------
      // ADD JOB
      // -------------------------------
      .addCase(addJob.fulfilled, (state, action) => {
        // add the new job to list
        state.jobs.push(action.payload);
        state.isSuccess = true;
      })

      // -------------------------------
      // APPLY FOR JOB
      // -------------------------------
      .addCase(applyForJob.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(applyForJob.fulfilled, (state, action) => {
        state.isLoading = false;
        state.isSuccess = true;
        state.message = action.payload?.message || "Applied successfully";
      })
      .addCase(applyForJob.rejected, (state, action) => {
        state.isLoading = false;
        state.isError = true;
        state.message = action.payload;
      });
  },
});

export default jobSlice.reducer;
